import 'dart:io';

import 'package:flutter/foundation.dart';
import 'package:path/path.dart' as p;

import '../../../services/app_paths.dart';
import '../models/infinite_canvas_config.dart';

/// 本工具生成的 override 文件名。
///
/// 故意不叫 `docker-compose.override.yml`：compose 会在用户手敲
/// `docker compose up` 时**隐式自动加载**那个名字，而我们的命令又显式 `-f`
/// 了它一次。用独立文件名让「本工具管理」与「用户手动」完全分离（design D6）。
const String kOverrideFileName = 'docker-compose.v8box.yml';

/// 标记注释的首行。只有以它开头的文件才会被本工具重写；别的文件先备份
/// （spec: 运行时配置以 override 注入而不修改上游工程文件）。
const String kOverrideMarker =
    '# Generated by V8WorkToolbox infinite canvas tool';

/// 上游 compose 文件里的服务名。
///
/// 提成常量是因为上游改名时 compose **不会**因为 override 引用了个不存在
/// 的服务而报错，要到 `up` 时才炸——那时必须告诉用户去核对服务名，而不是
/// 让他盲目重试（spec: 容器启停与状态呈现的失败路径）。
const String kComposeServiceName = 'app';

/// Override 文件的生成、读取与安全重写。
///
/// **为什么用 override 而不是改上游 compose 文件**：直接改原文件用户
/// `git pull` 一次就丢，且会让仓库出现本地未提交改动，干扰后续升级。
/// override 是 compose 原生的「本地部署差异」机制，对上游零侵入。
///
/// **与 Toonflow 版的差异**：只有两项职责——把端口覆盖成回环、按需覆盖
/// 镜像。没有 bind mount，也没有 `user:` 对齐：无限画布的容器是 nginx 静态
/// 服务器，不写任何数据目录，那两项在这里是无意义噪音（spec: 运行时配置以
/// override 注入而不修改上游工程文件）。
class InfiniteCanvasOverrideStore {
  InfiniteCanvasOverrideStore._();
  static final InfiniteCanvasOverrideStore instance =
      InfiniteCanvasOverrideStore._();

  /// 生成 override 内容。
  ///
  /// `!override` 标签必须带：compose 对 `ports` 的默认合并行为是**追加**，
  /// 不带标签会导致 3000 同时绑两个端口（上游的 `"3000:3000"` 还在）。
  ///
  /// 端口只绑 `127.0.0.1`：上游默认 `"3000:3000"` 绑全部网卡，等于把工作台
  /// 暴露给同局域网所有人——而工作台的浏览器本地存储里存着用户的 API Key
  /// （spec: 端口分配与冲突预检）。
  String render(InfiniteCanvasConfig config, {String? image}) {
    final buffer = StringBuffer()
      ..writeln(kOverrideMarker)
      ..writeln('# 本文件由 V8WorkToolbox 的无限画布工具自动生成与维护。')
      ..writeln('# 手工修改会在下次启动时被覆盖；如需长期定制请改上游')
      ..writeln('# docker-compose.yml，并把这个工具的端口配置对齐。')
      ..writeln('services:')
      ..writeln('  $kComposeServiceName:');
    final resolved = image ??
        (config.useLocalImage ? InfiniteCanvasConfig.localImageName : null);
    if (resolved != null && resolved.trim().isNotEmpty) {
      buffer.writeln('    image: ${_escapeYaml(resolved.trim())}');
    }
    buffer
      ..writeln('    ports: !override')
      ..writeln('      - "127.0.0.1:${config.httpPort}:3000"');
    return buffer.toString();
  }

  /// 把字符串转成 YAML 双引号标量的**内部**形态。
  static String _escapeYaml(String value) =>
      value.replaceAll(r'\', r'\\').replaceAll('"', r'\"');

  /// override 文件路径。
  String pathFor(String projectDir) =>
      p.join(projectDir, kOverrideFileName);

  /// 读取现有内容；不存在返回 null。
  String? read(String projectDir) {
    final file = File(pathFor(projectDir));
    if (!file.existsSync()) return null;
    try {
      return file.readAsStringSync();
    } catch (e) {
      debugPrint('[InfiniteCanvasOverrideStore] 读取 override 失败: $e');
      return null;
    }
  }

  /// 该文件是否由本工具生成（可安全重写）。
  bool isManaged(String projectDir) {
    final content = read(projectDir);
    if (content == null) return false;
    return content.trimLeft().startsWith(kOverrideMarker);
  }

  /// 写入 override。
  ///
  /// 返回是否发生了备份（调用方需告知用户——非本工具生成的文件被替换是
  /// 意外情况，静默覆盖违反 spec 的承诺）。
  bool write(
    String projectDir,
    InfiniteCanvasConfig config, {
    String? image,
  }) {
    final file = File(pathFor(projectDir));
    var backedUp = false;

    if (file.existsSync() && !isManaged(projectDir)) {
      final backup = File(
        p.join(
          AppPaths.infiniteCanvasDir.path,
          '$kOverrideFileName.bak-${DateTime.now().millisecondsSinceEpoch}',
        ),
      );
      try {
        AppPaths.infiniteCanvasDir.createSync(recursive: true);
        file.copySync(backup.path);
        backedUp = true;
        debugPrint(
          '[InfiniteCanvasOverrideStore] 已备份非托管 override → ${backup.path}',
        );
      } catch (e) {
        debugPrint('[InfiniteCanvasOverrideStore] 备份失败（仍继续写入）: $e');
      }
    }

    file.writeAsStringSync(render(config, image: image));
    return backedUp;
  }

  /// 删除 override（回滚用）。仅删除本工具生成的那份。
  bool remove(String projectDir) {
    final file = File(pathFor(projectDir));
    if (!file.existsSync()) return false;
    if (!isManaged(projectDir)) return false;
    try {
      file.deleteSync();
      return true;
    } on FileSystemException catch (e) {
      debugPrint('[InfiniteCanvasOverrideStore] 删除 override 失败: $e');
      return false;
    }
  }

  /// 测试用：解析 override 的关键字段，供断言。
  ///
  /// 不引入 YAML 解析库——只需要验证服务名、镜像与端口三项，正则足够且不会
  /// 因为上游 compose 结构变化而崩。
  static Map<String, String> decodeOverride(String content) {
    final result = <String, String>{};
    final serviceMatch = RegExp(r'^  (\S+):$', multiLine: true).firstMatch(
      content,
    );
    if (serviceMatch != null) result['service'] = serviceMatch.group(1)!;
    final imageMatch = RegExp(r'image:\s*"?([^"\n]+)"?').firstMatch(content);
    if (imageMatch != null) result['image'] = imageMatch.group(1)!.trim();
    final portMatch = RegExp(r'127\.0\.0\.1:(\d+):3000').firstMatch(content);
    if (portMatch != null) result['hostPort'] = portMatch.group(1)!;
    if (content.contains('ports: !override')) result['portsOverride'] = 'true';
    return result;
  }
}
